# --- build the 8 panes (each = 3 lists of 4 cells) ---
def list_html(items, idx):
    # items: list of (type, adj)
    cols = {'d':'Домин.','i':'Искр.','s':'Уст.','c':'Сист.'}
    parts = []
    for cell_i, (typ, adj) in enumerate(items):
