# -*- coding: utf-8 -*-
import json, html as htmlmod

groups = json.load(open('/tmp/groups.json'))
assert len(groups) == 24, len(groups)

COLS = {'d':'Домин.','i':'Экбр.','s':'Уст.','c':'Сист.'}

def list_html(items):
    parts = []
    for (typ, adj) in items:
        col = COLS.get(typ, '')
        parts.append('<div class="list__cell"><span class="cell-tag cell-tag--{ty}">{c}</span><div class="list__item" data-type="{ty}" draggable="true" role="button" tabindex="-1" aria-label="{ty}">{adj}</div></div>'.format(
            ty=typ, c=col, adj=htmlmod.escape(adj)))
    return '<div class="list" aria-label="вопрос {i}"><div class="list__row">{cells}</div></div>'.format(cells=''.join(parts))

panes = []
for p in range(8):
    cells = ''.join(list_html(groups[p*3+k]['items']) for k in range(3))
    panes.append('<div class="pane" data-pane="{p}">'.format(p=p) + cells + '</div>')

PANE_HTML = '\n      '.join(panes)

parts = []
def w(s):
    parts.append(s)

w('<!DOCTYPE html>\n<html lang="ru">\n<head>\n')
