w(r'''

var DISC_QUESTIONS = %s;
var DISC_ORDER = ["d","i","s","c"];
var DISC_LABELS = {
  d:{name:"Доминантный",color:"#e2533b"},
  i:{name:"Экспресcивный",color:"#f5a623"},
  s:{name:"Установочный",color:"#39b54a"},
  c:{name:"Систематичный",color:"#2f7bf6"}
};
var DISC_BANDS = {
  d:"Доминантный: ориентирован на результат, решает задачи напрямую, готов брать инициативу и брать ответственность за решения. Ценит скорость, вызовы и свободу действий.",
  i:"Экспресcивный: ориентирован на людей, вдохновляет и влияет, легко заводит знакомства. Ценит признание, командную энергию и обмен идеями.",
  s:"Установочный: ориентирован на стабильность, надёжен и терпелив, хороший слушатель. Ценит гармонию, предсказуемость и длительные отношения.",
  c:"Систематичный: ориентирован на качество и точность, внимателен к деталям. Ценит стандарты, анализ и обоснованные решения."
};

var state = { step:0, scores:null, answers:null };

var qs = function(s, r){ return (r||document).querySelector(s); };
var qsa = function(s, r){ return Array.from((r||document).querySelectorAll(s)); };

var wizard = qs("#wizard");
var result = hs("#result");
var progBar = hs("#progBar");

var btnStart = hs("#openBtn");
var btnClose wizard = qsa("[data-close]", wizard);
var tabs = qsa("[data-step]", wizard);
var paneEls = qsa("[data-pane]", wizard);
var btnPrev = hs("#prevBtn");
var btnNext = hs("#nextBtn");
var btnFinish = hs("#finishBtn");

function hs(s){ return document.querySelector(s); }

function openModal(m){ if(!m) return; m.classList.add("is-open"); m.setAttribute("aria-hidden","false"); document.documentElement.classList.add("no-scroll"); }
function closeModal(m){ if(!m) return; m.classList.remove("is-open"); m.setAttribute("aria-hidden","true"); document.documentElement.classList.remove("no-scroll"); }

btnStart.addEventListener("click", function(e){ e.preventDefault(); openModal(wizard); render(); });

tabs.forEach(function(t){
  t.addEventListener("click", function(e){ e.preventDefault(); setStep(Number(t.dataset.step)); });
});

btnPrev.addEventListener("click", function(){ setStep(state.step - 1); });
btnNext.addEventListener("click", function(){ setStep(state.step + 1); });
btnFinish.addEventListener("click", function(){ closeModal(wizard); calcResults(); openModal(result); });

qsa(".modal__close").forEach(function(b){ b.addEventListener("click", function(){ closeModal(b.closest(".modal")); }); });
qsa("[data-close]").forEach(function(x){ x.addEventListener("click", function(){ x.closest(".modal").remove("is-open"); }); });

document.addEventListener("keydown", function(e){ if(e.key==="Escape"){ closeModal(wizard); closeModal(result); } });

document.getElementById("restartBtn").addEventListener("click", function(){
  state.scores = null; state.answers = null;
  buildPanels();
  state.step = 0;
  closeModal(result);
  openModal(wizard);
   render();
});

function setStep(n){
  state.step = Math.max(0, Math.min(7, n));
   render();
}

function render(){
  tabs.forEach(function(t){
    var i = Number(t.dataset.step);
    active = i===state.step;
    t.classList.toggle("is-active", active);
    t.setAttribute("aria-selected", active?"true":"false");
  });
  paneEls.forEach(function(p){ p.classList.toggle("is-active", Number(p.dataset.pane)===state.step); });
  progressBar.style.width = ((state.step+1)/8*100)+"%";
  btnPrev.disabled = state.step===0;
  btnNext.hidden = state.step===7;
  btnFinish.hidden = state.step!==7;
}

function collectAnswers(){
  var out = {};
  qsa(".disc-list", wizard).forEach(function(ul, idx){
    var order = qsa("li", ul).map(function(li){ return li.getAttribute("data-type"); });
    out[idx] = order;
  });
  return out;
}

function collectPayload(){
  var payload = [];
  qsa(".disc-list", wizard).forEach(function(ul, listIndex){
    qsa("li", ul).forEach(function(li, pos){
      payload.push({list:listIndex, pos:pos, type:li.getAttribute("data-type")});
    });
  });
  return payload;
}

function score(payload){
  var maj=[], min=[];
  payload.forEach(function(x){ if(x.pos===0) maj.push(x.type); if(x.pos===3) min.push(x.type); });
  var count=function(arr,ch){ return arr.reduce(function(a,v){return a+(v===ch?1:0);0};};
  return {
    d: count(maj,"d")-count(min,"d"),
    i: count(maj,"i")-count(min,"i"),
    s: count(maj,"s")-count(min,"s"),
    c: count(maj,"c")-count(min,"c")
  };
}

function calcResults(){
  state.scores = score(collectPayload());
}

function buildPanels(){
  var container = hs("#panes");
  container.innerHTML = "";
  DISC_QUESTIONS.forEach(function(question){
    var cells = question.items.map(function(t){
      return '<div class="list__cell"><input type="text" data-type="'+t.type+'" value="'+t.text+'" style="position:absolute;opacity:0;pointer-events:none">'+'<div class="list__item" data-type="'+t.type+'" draggable="true" role="button" tabindex="-1" style="color:'+DISC_LABELS[t.type].color+'">'+t.text+'</div></div>';
    }).join('');
    var pane = document.createElement('div');
    pane.className = 'pane';
    pane.setAttribute('data-pane', ...);
    pane.innerHTML = '<div class="list__step">В 1</div><div class="list" aria-label="привод 1">'+'<div class="list__row">'+'<div class="list__cell"><div class="list__item" data-type="d" draggable="true" role="button" aria-label="D">'+question.items[0].text+'</div></div>'+'</div></div>';
    container.appendChild(pane);
  });
  qsa(".disc-list").forEach(function(ul){ setupList(ul); });
}
''')

