# -*- coding: utf-8 -*-
# Build self-contained index.html from verified verified reference sources.

def read(p):
    with open(p, "r", encoding="utf-8") as f:
        return f.read()

styles = read("styles.css")
questions_json = read("questionsdata.js")

# -----------------------------
# app.js : adapted test logic (from disc_patched.js), no external requests
# -----------------------------
APP_JS = r"""
// DISC copy — self-contained behaviour. Adapted reference scoring; results
// are computed inline (no email/apruve/redirect/CDN).
(() => {
  const qs = (s, r = document) => r.querySelector(s);
  const qsa = (s, r = document) => Array.from(r.querySelectorAll(s));
  const el = (tag) => document.createElement(tag);

  // base64url (matches reference)
  function base64UrlEncode(bytes){
    let bin = "";
    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
  }

  // ---- state ----
  let step = 0;
  let lastFocus = null;
  let resultToken = null;
  const RESULTS_KEY = "disc_copy_token_v1";
  const MAX_STEP = 7;

  // ---- DOM anchors ----
  const wizard = qs("#wizard");
  const modalOverlay = document.querySelector(".modal-overlay");
  const closeBtns = qsa("[disc-close]", wizard);
  const startBtn = qs("#startBtn");
  const tabs = qsa(".tab", wizard);
  const tabsScroller = qs(".tabs", wizard);
  const panes = qsa(".pane", wizard);
  const prevBtn = qs("[disc-prev]");
  const nextBtn = qs("[disc-next]");
  const finishBtn = qs("[disc-finish]");
  const progressBar = qs("#progressBar");
  const resultModal = qs("#result");
  const closeResultBtn = qs("#closeResult");
  const restartBtn = qs("#restartBtn");
  const chartBar = qs("#chartBar");
  const chart = qs("#chart");
  const percentList = qsa(".percent-value", resultModal);

  // ----- data (injected) -----
  const QUESTIONS = DATA;

  const TYPES = ["d","i","s","c"];
  const TYPE_META = {
    d: { label: "Доминантный", color: "#e2533a", desc: "Решения, результат, контроль." },
    i: { label: "Экспрессивный", color: "#f5a525", desc: "Общение, влияние, энтузиазм." },
    s: { label: "Установочный", color: "#3aa64c", desc: "Надёжность, спокойствие, стабильность." },
    c: { label: "Систематичный", color: "#2f6fdf", desc: "Качество, точность, следование правилам." }
  };

  // ----- build 8 panes x 3 rows -----
  function buildPanels() {
    panes.forEach(function(pane, i){
      pane.innerHTML =
        '<div class="pane-title">'+(i+1)+'</div>'+
        '<div class="pane-note">в каждой строке выберите один вариант, затем переместите ниже по мере необходимости</div>'+
        renderRows(i) +
        '<div class="lists"></div>';
      const listsWrap = pane.querySelector(".lists");
      for (let row = 0; row < 3; row++) {
        const lis = QUESTIONS[i].items.slice(row*3, row*3+3);
        const ul = el("ul");
        ul.className = "disc-list";
        lis.forEach(function(it, c){
          const li = el("li");

          const li = el("li");
          li.className = "disc-item";
          li.draggable = true;
          li.dataset.type = it.type;
          li.textContent = it.label;
          ul.appendChild(li);
        });
        listsWrap.appendChild(ul);
      }
    });
    initSortable();
  }

  function renderRows(start){
    let cells = '';
    for (let r = 0; r < 3; r++){
      for (let c = 0; c < 3; c++){
        const idx = start*3 + c;
        const it = QUESTIONS[start].items[idx];
        cells += '<div class="cell" data-cell="'+idx+'">'+(
          it ? '<div class="cell-inner"><div class="cell-item is-done" data-idx="'+idx+'">'+it.label+'</div></div>' : ''
        )+'</div>';
      }
    }
    return '<div class="grid3">'+cells+'</div>';
  }

  // ----- sortable lists (+ fallback) -----
  const dragByHandle = !!(window.matchMedia && window.matchMedia("(pointer: coarse)").matches);

  function makeSortable(ul){
    const items = () => qsa("li", ul);
    items().forEach(function(li){
      li.addEventListener("dragstart", function(e){
        li.classList.add("is-dragging");
        e.dataTransfer.effectAllowed = "move";
      });
      li.addEventListener("dragend", function(){
        li.classList.remove("is-dragging");
        items().forEach(function(x){ x.classList.remove("is-over"); });
      });
      li.addEventListener("dragover", function(e){
        e.preventDefault();
        const dragging = qsa(".is-dragging", ul)[0];
        if (!dragging || dragging === li) return;
        li.classList.add("is-over");
        const rect = li.getBoundingClientRect();
        const before = e.clientY - rect.top < rect.height / 2;
        ul.insertBefore(dragging, before ? li : li.nextSibling);
      });
    });
  }
  function initSortable(){
    qsa(".disc-list", wizard).forEach(makeSortable);
  }

  // ----- scroll lock -----
  function syncScrollLock(){
    const anyOpen = !!qs(".disc-modal.is-open");
    document.toggleClass = document.toggleClass || function(c,o){ this.classList.toggle(c,o); };
    document.toggleClass.call(document.documentElement, "no-scroll", anyOpen);
    document.toggleClass.call(document.body, "no-scroll", anyOpen);
  }
  function openModal(el){
    el.classList.add("is-open");
    el.setAttribute("aria-hidden","false");
    modalOverlay.classList.add("is-open");
    syncScrollLock();
  }
  function closeModal(el){
    el.classList.remove("is-open");
    el.setAttribute("aria-hidden","true");
    modalOverlay.classList.remove("is-open");
    syncScrollLock();
    if (lastFocus && typeof lastFocus.focus === "function") lastFocus.focus({preventScroll:true});
  }
  function openWizard(){
    lastFocus = document.activeElement;
    openModal(wizard);
    qs(".close-btn", wizard).focus({preventScroll:true});
    render();
  }
  function closeWizard(){ closeModal(wizard); }

  // ----- steps -----
  function setStep(n){
    step = Math.max(0, Math.min(MAX_STEP, n));
    render();
  }
  function render(){
    tabs.forEach(function(t){
      const is = Number(t.dataset.index) === step;
      t.classList.toggle("is-active", is);
      t.setAttribute("aria-selected", is ? "true" : "false");
    });
    panes.forEach(function(p){ p.classList.toggle("is-active", Number(p.dataset.index) === step); });
    prevBtn.disabled = step === 0;
    finishBtn.hidden = step !== MAX_STEP;
    nextBtn.hidden = step === MAX_STEP;
    const pct = ((step + 1) / 8) * 100;
    progressBar.style.width = pct + "%";
  }

  // ----- score -----
  function collectPayload(){
    const payload = [];
    qsa(".disc-list", wizard).forEach(function(ul, listIndex){
      qsa("li", ul).forEach(function(li, idx){
        payload.push({ list: listIndex, pos: idx, type: li.dataset.type });
      });
    });
    return payload;
  }
  function score(payload){
    const maj = [], min = [];
    payload.forEach(function(x){
      if (x.pos === 0) maj.push(x.type);
      if (x.pos === 3) min.push(x.type);
    });
    const count = function(arr,ch){ return arr.reduce(function(a,v){ return a + (v===ch?1:0); }, 0); };
    const out = {};
    TYPES.forEach(function(t){ out[t] = count(maj,t) - count(min,t); });
    return out;
  }

  // ----- result rendering -----
  function computeScores(){
    return score(collectPayload());
  }
  function toToken(scores){
    try {
      const obj = { v:1, ts: Date.now(), score: scores };
      const data = new TextEncoder().encode(JSON.stringify(obj));
      const s = btoa(String.fromCharCode.apply(null, Array.from(data)));
      return s.replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
    } catch(e){
      return "";
    }
  }

  function maxType(scores){
    let best = "d", bestScore = -1e9;
    TYPES.forEach(function(t){
      if (scores[t] > bestScore){ bestScore = scores[t]; best = t; }
    });
    return best;
  }

  function buildBarScores(scores, meta){
    const all = TYPES.map(function(t){ return { t:t, label:TYPE_META[t].label, score:scores[t] }; });
    return all.map(function(o){
      const row = '<div class="bar-row"><div class="bar-label"><span class="bar-dot" style="background:'+TYPE_META[o.t].color+'"></span>'+o.label+'</div>';
      const scoreTxt = o.score > 0 ? '+'+o.score : String(o.score);
      return row+'<div class="bar-value">'+scoreTxt+'</div>'+
        '<div class="bar-track"><div class="bar-fill" style="width:0%; background:'+TYPE_META[o.t].color+'"></div></div>'+
        '</div>';
    }).join('');
  }

  function showResult(scores){
    openModal(resultModal);
    chart.style.setProperty("--d", Math.max(0, scores.d)*10 + "%");
    chart.style.setProperty("--i", Math.max(0, scores.i)*10 + "%");
    chart.style.setProperty("--s", Math.max(0, scores.s)*10 + "%");
    chart.style.setProperty("--c", Math.max(0, scores.c)*10 + "%");
    const bar = document.getElementById("chartInner");
    if (bar) bar.innerHTML = buildBarScores(scores, TYPE_META);
    const best = maxType(scores);
    document.getElementById("chartType").textContent = TYPE_META[best].label;
    document.getElementById("chartScore").innerHTML = 'Доминантность <b>D</b> в Вашем типе выше среднего.<br>Потенциал для руководства — очень высокий.';
    resultToken = toToken(scores);
    try { if (window.sessionStorage) sessionStorage.setItem(RESULTS_KEY, resultToken); } catch(e){}
  }

  function renderResults(){
    const s = computeScores();
    showResult(s);
  }

  // ----- wire -----
  function init(){
    buildPanels();
    render();
    if (startBtn) startBtn.addEventListener("click", function(e){ e.preventDefault(); openWizard(); });
    closeBtns.forEach(function(b){ b.addEventListener("click", function(e){ e.preventDefault(); closeWizard(); }); });
    if (modalOverlay) modalOverlay.addEventListener("click", function(e){ if (e.target === modalOverlay){ closeModal(wizard); } });
    if (prevBtn) prevBtn.addEventListener("click", function(){ setStep(step - 1); });
    if (nextBtn) nextBtn.addEventListener("click", function(){ setStep(step + 1); });
    if (finishBtn) finishBtn.addEventListener("click", function(e){ e.preventDefault(); renderResults(); });
    if (closeResultBtn) closeResultBtn.addEventListener("click", function(e){ e.preventDefault(); closeModal(resultModal); });
    if (restartBtn) restartBtn.addEventListener("click", function(e){ e.preventDefault(); window.location.reload(); });
    document.addEventListener("keydown", function(e){ if (e.key === "Escape"){ closeModal(wizard); closeModal(resultModal); } });
    syncScrollLock();
  }

  document.addEventListener("DOMContentLoaded", init);
})();
"""

